import { describe, expect, it } from 'vitest';
import { locales } from '@nestself/contracts';
// Test-only: the API does not depend on the i18n package. The catalogs' Cyrillic
// is generated by this function, and the email copy must agree with it.
import { transliterate } from '../../../../packages/i18n/scripts/transliterate-core.mjs';
import { EMAIL_TEMPLATES } from './email-templates.js';
import type { MailTemplate } from './mailer.js';

/**
 * Templates whose copy is one English text in all four locale slots: their
 * reader is the operations mailbox, so there is nothing to translate and
 * `sr-Cyrl` is not a transliteration of `sr-Latn`.
 */
const ENGLISH_ONLY: readonly MailTemplate[] = ['ops_certificate_alert'];

/** The params each template takes: the contract its callers rely on. */
const PARAMS: Record<MailTemplate, string[]> = {
  invitation: ['inviterDisplayName', 'link', 'organizationName'],
  step_up_code: ['code', 'minutes'],
  sso_bind_code: ['code', 'minutes'],
  ops_certificate_alert: ['adminUrl', 'daysLeft', 'expiresAt', 'organizationName', 'providerName'],
};

function placeholders(copy: { subject: string; text: string }): string[] {
  const names = [...(copy.subject + '\n' + copy.text).matchAll(/\{\{(\w+)\}\}/g)].map(
    (match) => match[1]!,
  );
  return [...new Set(names)].sort();
}

const entries = Object.entries(EMAIL_TEMPLATES) as Array<
  [MailTemplate, (typeof EMAIL_TEMPLATES)[MailTemplate]]
>;
const localised = entries.filter(([name]) => !ENGLISH_ONLY.includes(name));

describe('EMAIL_TEMPLATES', () => {
  it('has exactly the four templates', () => {
    expect(Object.keys(EMAIL_TEMPLATES).sort()).toEqual(Object.keys(PARAMS).sort());
  });

  it('has every template in all four locales, none of them empty', () => {
    for (const [name, byLocale] of entries) {
      expect(Object.keys(byLocale).sort(), name).toEqual(['en', 'hu', 'sr-Cyrl', 'sr-Latn']);
      expect(Object.keys(byLocale).sort(), name).toEqual([...locales].sort());
      for (const locale of locales) {
        expect(byLocale[locale].subject.trim(), `${name} ${locale} subject`).not.toBe('');
        expect(byLocale[locale].text.trim(), `${name} ${locale} text`).not.toBe('');
      }
    }
  });

  it('sr-Cyrl is the transliteration of sr-Latn', () => {
    for (const [name, byLocale] of localised) {
      expect(byLocale['sr-Cyrl'].subject, name).toBe(transliterate(byLocale['sr-Latn'].subject));
      expect(byLocale['sr-Cyrl'].text, name).toBe(transliterate(byLocale['sr-Latn'].text));
    }
  });

  it('writes the localised copy in the language of its locale, not in English', () => {
    for (const [name, byLocale] of localised) {
      expect(byLocale['sr-Latn'].text, name).not.toBe(byLocale.en.text);
      expect(byLocale.hu.text, name).not.toBe(byLocale.en.text);
    }
  });

  it('the English-only copy is the same text in every locale', () => {
    for (const name of ENGLISH_ONLY) {
      const byLocale = EMAIL_TEMPLATES[name];
      for (const locale of locales) {
        expect(byLocale[locale], `${name} ${locale}`).toEqual(byLocale.en);
      }
    }
  });

  it('placeholders match across locales', () => {
    for (const [name, byLocale] of entries) {
      for (const locale of locales) {
        expect(placeholders(byLocale[locale]), `${name} ${locale}`).toEqual(
          placeholders(byLocale.en),
        );
      }
    }
  });

  it('each template uses exactly the params its callers pass', () => {
    for (const [name, byLocale] of entries) {
      for (const locale of locales) {
        expect(placeholders(byLocale[locale]), `${name} ${locale}`).toEqual(PARAMS[name]);
      }
    }
  });
});
